UPDATE stock_risk_grade SET var_975=#{var975}, risk_grade=#{riskGrade}, volatility=#{volatility},
    price_from=#{priceFrom}, price_to=#{priceTo}, calculated_at=#{calculatedAt},
    synced_at=#{syncedAt}, analysis_version=#{analysisVersion}
WHERE domestic_product_id=#{domesticProductId}
AND (price_to < #{priceTo} OR (price_to=#{priceTo} AND analysis_version < #{analysisVersion}))
